INSERT INTO public.filiales (id, code, name, slogan, description, sector, logo_url, cover_image_url, phone, email, locations) VALUES (1, 'frivia', 'FRIVIA', 'Tout simplement délicieux', 'FRIVIA est une chaîne moderne de restauration rapide spécialisée dans les menus Frites & Viande, combinant rapidité, goût, hygiène et accessibilité avec des standards internationaux adaptés aux réalités locales.', 'Restauration rapide & Fast-food', '/logo.svg', 'https://images.unsplash.com/photo-1568901346375-23c9450c58cd?ixlib=rb-1.2.1&auto=format&fit=crop&w=1350&q=80', '+243 814 119 635', 'frivia@pkglobalpartners.com', 'Kinshasa & Goma, RDC') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.filiales (id, code, name, slogan, description, sector, logo_url, cover_image_url, phone, email, locations) VALUES (2, 'elikya', 'ELIKYA COFFEE', 'L''espoir infusé dans chaque arôme', 'ELIKYA COFFEE est la marque premium de café de PK GLOBAL PARTNERS, née du terroir exceptionnel du Kivu. Spécialisée dans la production, la transformation et la commercialisation de café Arabica et Robusta avec un impact social durable.', 'Agroalimentaire & Café de Terroir', '/logo.svg', 'https://images.unsplash.com/photo-1559056199-641a0ac8b3f4?ixlib=rb-1.2.1&auto=format&fit=crop&w=1350&q=80', '+243 814 119 635', 'elikya@pkglobalpartners.com', 'Kivu, Goma & Kinshasa, RDC') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.filiales (id, code, name, slogan, description, sector, logo_url, cover_image_url, phone, email, locations) VALUES (3, 'youpi', 'YOUPI PÂTISSERIE', 'Savourez la vie en douceur', 'YOUPI PÂTISSERIE est une marque moderne de boulangerie-pâtisserie développée par PK GLOBAL PARTNERS, alliant qualité artisanale, constance professionnelle et accessibilité premium pour le consommateur urbain.', 'Boulangerie & Pâtisserie Moderne', '/logo.svg', 'https://images.unsplash.com/photo-1578985545062-69928b1d9587?ixlib=rb-1.2.1&auto=format&fit=crop&w=1350&q=80', '+243 814 119 635', 'youpi@pkglobalpartners.com', 'Goma & Kinshasa, RDC') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.services_poles (id, title, category, description, icon, active, display_order) VALUES (1, 'Agroalimentaire & Transformation', 'Pôle Industriel', 'Valorisation locale de la production agricole congolaise, café d''excellence du Kivu, restauration rapide structurée et boulangerie moderne.', 'fa-utensils', true, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.services_poles (id, title, category, description, icon, active, display_order) VALUES (2, 'Investissement & Financement', 'Pôle Financier', 'Structuration de véhicules de co-investissement, capital développement pour PME émergentes et accompagnement de deals stratégiques.', 'fa-chart-line', true, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.services_poles (id, title, category, description, icon, active, display_order) VALUES (3, 'Distribution & Logistique', 'Pôle Opérationnel', 'Maîtrise de la chaîne du froid, circuits de distribution urbains et raccordement des bassins de production aux grands centres de consommation.', 'fa-truck-fast', true, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.services_poles (id, title, category, description, icon, active, display_order) VALUES (4, 'Conseil Stratégique & Incubation', 'Pôle Accélération', 'Due diligence, gouvernance d''entreprise, passage à l''échelle et mentorat pour les entrepreneurs lauréats des appels à projets.', 'fa-lightbulb', true, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.call_for_projects (id, title, slug, description, target_sector, budget_indicatif, eligibility, deadline, status) VALUES (1, 'Appel à Projets 2026 : AgriTech & Transformation Agroalimentaire RDC', 'appel-projets-agritech-2026', 'Sélection et financement de 5 projets innovants dans la transformation locale des matières premières agricoles, la chaîne du froid et la distribution.', 'Agroalimentaire & Chaîne de valeur', 'Jusqu''à 150 000 USD par lauréat', 'Entreprises enregistrées en RDC, existence minimum de 1 an, impact social mesurable auprès des producteurs locaux.', '2026-12-15 23:59:59', 'open') ON CONFLICT (id) DO NOTHING;
